parameters.jsCode:
const body = $input.first().json.body || $input.first().json || {};

const rawPhone = String(body.customer_phone || '');
const digits = rawPhone.replace(/\D/g, '');
let phone62 = '';
if (digits.length >= 9) {
  if (digits.startsWith('0')) {
    phone62 = '62' + digits.slice(1);
  } else if (digits.startsWith('62')) {
    phone62 = digits;
  } else {
    phone62 = '62' + digits;
  }
}

const chatId = phone62 ? `${phone62}@c.us` : '';
const isValidPhone = Boolean(chatId && phone62.length >= 10 && phone62.length <= 15);

const amountNum = Number(body.total_amount || 0);
const formattedTotal = new Intl.NumberFormat('id-ID').format(amountNum);

const customerName = body.customer_name || 'Customer';
const productName = body.product_name || 'Travel Gear';
const pickupLocation = body.pickup_location_name || '-';
const orderCode = body.order_code || '-';
const qty = body.quantity || 1;
const startDate = body.start_date || '-';
const endDate = body.end_date || '-';
const durationDays = body.duration_days || 1;

const messageText = [
  `Halo *${customerName}*!`,
  '',
  'Pembayaran sewa perlengkapan *JavaPack* kamu sudah berhasil dikonfirmasi.',
  '',
  `*Kode Order:* ${orderCode}`,
  `*Produk:* ${productName} (${qty} unit)`,
  `*Lokasi Pickup:* ${pickupLocation}`,
  `*Tanggal Sewa:* ${startDate} s/d ${endDate} (${durationDays} hari)`,
  `*Total Bayar:* Rp ${formattedTotal}`,
  '*Status:* PAID',
  '',
  'Silakan tunjukkan kode order ini saat pengambilan gear di lokasi pickup. Terima kasih telah memilih JavaPack!'
].join('\n');

return [
  {
    json: {
      ...body,
      phone62,
      chatId,
      isValidPhone,
      messageText
    }
  }
];

